function showBasket(){open(tr('Your saved evidence','Vos données retenues'),'basket');const brief=read('brief',{});$('gcw-content').innerHTML='<p>'+esc(tr('Combine saved findings and tables into a sourced briefing. Your notes stay in this browser until you export them.','Rassemblez les résultats et tableaux retenus dans une note avec leurs sources. Vos notes restent dans ce navigateur jusqu’à leur exportation.'))+'</p><div class="gcw-two">'+field('gcw-brief-title',tr('Briefing title','Titre de la note'),'<input id="gcw-brief-title" maxlength="180" value="'+esc(brief.title||tr('Employment equity briefing','Note sur l’équité en matière d’emploi'))+'">')+field('gcw-brief-notes',tr('Purpose or notes','Objet ou notes'),'<textarea id="gcw-brief-notes" maxlength="6000">'+esc(brief.notes||'')+'</textarea>')+'</div><div class="gcw-actions">'+button('export-html',tr('Download briefing','Télécharger la note'),'gcw-btn-primary')+button('export-text',tr('Plain text','Texte brut'))+button('export-json',tr('Export evidence','Exporter les données retenues'))+button('import-json',tr('Import evidence','Importer les données retenues'))+'<input type="file" id="gcw-import-file" accept=".json,application/json" hidden></div><p class="gcw-small">'+esc(tr('The briefing downloads as an HTML document. Open it to print or save as PDF. Evidence export keeps tables and source details for another browser.','La note est téléchargée au format HTML. Ouvrez-la pour l’imprimer ou l’enregistrer en PDF. L’exportation des données retenues conserve les tableaux et leurs sources pour un autre navigateur.'))+'</p><div id="gcw-evidence-list">'+(basket.length?basket.map((f,i)=>'<article class="gcw-result"><span class="gcw-result-meta">'+(i+1)+' · '+esc(f.period||'')+'</span><h3>'+esc(f.title)+'</h3><p>'+esc(f.text).slice(0,1400)+'</p><div class="gcw-result-actions">'+button('basket-trace',tr('Sources','Sources'),'gcw-btn-small','data-index="'+i+'"')+button('basket-up',tr('Move up','Monter'),'gcw-btn-small','data-index="'+i+'"'+(!i?' disabled':''))+button('basket-remove',tr('Remove','Retirer'),'gcw-btn-small','data-index="'+i+'"')+'</div></article>').join(''):'<p class="gcw-empty">'+esc(tr('No evidence saved yet. Save a guide answer, search result or table as you explore.','Aucune donnée retenue pour le moment. Retenez une réponse du guide, une référence ou un tableau pendant votre recherche.'))+'</p>')+'</div>';}

