function findOrgs(m,q){const n=' '+norm(q)+' ',names=[...new Set([...m.DEPTS.map(r=>r[0]),...Object.keys(m.PSES_DEPT),...Object.keys(m.EEG_DEPT)])].filter(s=>s!=='Public Service');const found=names.filter(name=>n.includes(' '+norm(name)+' ')||n.includes(' '+norm(m.DEPT_FR[name]||'__missing__')+' '));for(const [abbr,name] of Object.entries(aliases))if(n.includes(' '+abbr.toLowerCase()+' ')&&!found.includes(name))found.push(name);return found.sort((a,b)=>b.length-a.length);}
function findGroups(m,q){const n=norm(q).replace(/\bnon ?(?:racialized|racialises?|racisees?|racises?|indigenous|autochtones?)\b/g,'').replace(/(?:persons? |people |personnes? )?(?:without disabilities|sans handicap)\b/g,'');const tests={black:/\bblack|\bnoir/,i:/indigenous|autochtone/,d:/disabil|handicap/,v:/racial|racis|visible minorit/,w:/\bwomen\b|\bwoman\b|\bfemmes?\b/};return m.groups.filter(g=>tests[g.key].test(n));}
function questionCode(m,q){const n=norm(q),explicit=q.toUpperCase().match(/\bQ\d{2}\b/)?.[0];if(explicit&&m.PSES_QMETA[explicit])return explicit;if(/harass|harcel/.test(n))return /resolv|resol|regl|satisf/.test(n)?'Q63':'Q58';if(/discrimin/.test(n))return /resolv|resol|regl|satisf/.test(n)?'Q70':'Q65';if(/racism|racisme/.test(n))return /complaint|plainte|resolv|resol|satisf/.test(n)?'Q72':'Q49';if(/reprisal|represaill|recours|recourse/.test(n))return 'Q42';if(/promot/.test(n))return 'Q45';if(/speak|exprimer/.test(n))return 'Q24';if(/psycholog/.test(n))return 'Q52';if(/career|carriere/.test(n))return 'Q43';return null;}
function standardFact(m,overrides={}){return {title:'',text:'',url:'explorer.html#data',source:m.sources.statistics,sourceTitle:tr('Treasury Board of Canada Secretariat','Secrétariat du Conseil du Trésor du Canada'),period:tr('March 31, 2025','31 mars 2025'),population:tr('Core public administration employees covered by the employment equity tables. Women’s figures use pay-system information; other designated groups use voluntary self-identification.','Employés de l’administration publique centrale visés par les tableaux d’équité en matière d’emploi. Les chiffres sur les femmes proviennent du système de paye; les autres groupes désignés reposent sur l’auto-identification volontaire.'),calculation:tr('Published percentage, as reported by the source.','Pourcentage publié, tel que déclaré par la source.'),limitation:tr('Groups can overlap. A difference is not, on its own, evidence of discrimination or causation. Suppressed and missing values are not reconstructed.','Les groupes peuvent se chevaucher. Un écart ne démontre pas à lui seul une discrimination ni un lien de causalité. Les valeurs supprimées ou manquantes ne sont pas reconstituées.'),kind:'published figure',...overrides};}
function repFact(m,g,org='Public Service',year=2025){const row=org==='Public Service'?null:m.DEPTS.find(r=>r[0]===org);if(org!=='Public Service'&&(!row||year!==2025))return null;const rr=m.rep.find(r=>r.row_type==='representation'&&r.period_or_benchmark.includes(String(year)));const v=org==='Public Service'?(g.field?rr?.[g.field+'_pct']:year===2025?m.CPA[g.key]:null):row[['w','i','d','v'].indexOf(g.key)+2];if(g.key==='black'&&org!=='Public Service'||!numeric(v))return null;const bench=org==='Public Service'?(year===2025?m.WFA[g.key]:null):m.DEPT_WFA_2025[org]?.[g.key];const name=org==='Public Service'?tr('Whole public service','Ensemble de la fonction publique'):orgLabel(m,org);return standardFact(m,{title:groupLabel(g)+' · '+name,text:tr('Representation: ','Représentation : ')+pct(v)+(numeric(bench)?tr('. Workforce availability: ','. Disponibilité au sein de la population active : ')+pct(bench)+tr('. Difference: ','. Écart : ')+pp(Number(v)-Number(bench)):''),period:tr('March 31, ','31 mars ')+year,source:org==='Public Service'?m.sources.rep:m.DEPT_WFA_SOURCES[g.key],sourceTitle:tr('TBS representation and workforce availability table','Tableau du SCT sur la représentation et la disponibilité'),url:'explorer.html'+(org==='Public Service'?'?group='+g.picker+'#data':'?org='+encodeURIComponent(org)+'#orgprofile'),calculation:numeric(bench)?tr('Representation minus the matching workforce availability benchmark: ','Représentation moins la disponibilité de la population active correspondante : ')+fmt(v)+' − '+fmt(bench)+' = '+pp(Number(v)-Number(bench)):tr('Published representation percentage. No benchmark is supplied for this period or subgroup in this answer.','Pourcentage de représentation publié. Cette réponse ne fournit aucune référence pour cette période ou ce sous-groupe.'),value:Number(v),benchmark:numeric(bench)?Number(bench):null});}
