function seriesChart(points,label){const good=points.filter(p=>numeric(p[1]));if(good.length<2)return '';const w=520,h=220,pad=45,max=Math.max(10,Math.ceil(Math.max(...good.map(p=>Number(p[1])))/10)*10);const x=i=>pad+i*(w-pad*2)/(good.length-1),y=v=>h-35-Number(v)*(h-65)/max;return '<svg class="gcw-series" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="'+esc(label)+'"><title>'+esc(label)+'</title><line x1="'+pad+'" y1="'+(h-35)+'" x2="'+(w-pad)+'" y2="'+(h-35)+'" stroke="currentColor" opacity=".35"/><text x="12" y="30">'+max+'%</text><text x="15" y="'+(h-31)+'">0</text><polyline points="'+good.map((p,i)=>x(i)+','+y(p[1])).join(' ')+'" fill="none" stroke="currentColor" stroke-width="3"/>'+good.map((p,i)=>'<circle cx="'+x(i)+'" cy="'+y(p[1])+'" r="4" fill="currentColor"><title>'+esc(p[0]+': '+pct(p[1]))+'</title></circle><text x="'+x(i)+'" y="'+(h-10)+'" text-anchor="middle">'+esc(i===0||i===good.length-1||i%Math.ceil(good.length/5)===0?p[0]:'')+'</text>').join('')+'</svg>';}
