async function renderCommitCTA(org){const el=$('gcw-commit-cta');if(!el)return;try{const c=await ctaData();const out=$('gcw-commit-cta');if(!out||$('gcw-commit-org')?.value!==org)return;const o=c.organizations.find(x=>x.plan_name===org)||c.organizations.find(x=>[x.site_name,x.pses_name,x.name_en].includes(org));const head='<span class="gcw-card-tag">'+esc(tr('Call to Action, 2021 and 2024','Appel à l’action, 2021 et 2024'))+'</span><h3>'+esc(tr('Letter and self-assessment','Lettre et autoévaluation'))+'</h3>';if(!o){out.innerHTML=head+'<p>'+esc(tr('This organization has no 2021 letter or 2024 self-assessment in the Privy Council Office collections.','Cette organisation n’a ni lettre de 2021 ni autoévaluation de 2024 dans les collections du Bureau du Conseil privé.'))+'</p>'+link(localized('call-to-action.html'),tr('Compare the organizations that responded','Comparer les organisations qui ont répondu'));return;}const L=o.letter,S=o.self_assessment,G=[['indigenous',tr('Indigenous Peoples','peuples autochtones')],['racialized',tr('racialized employees','employés racisés')],['black',tr('Black employees','employés noirs')]];const pick=(k,st)=>S?G.filter(([g])=>S.goals[g+'_'+k]?.status===st).map(([,l])=>l):[];const said=(k,setL,wipL,noneL)=>{const a=pick(k,'set'),w=pick(k,'underway');return '<p>'+esc(a.length||w.length?[a.length?setL+a.join(', ')+'.':'',w.length?wipL+w.join(', ')+'.':''].filter(Boolean).join(' '):noneL)+'</p>';};const C=tr(': ','\u00a0: ');out.innerHTML=head+'<ul><li>'+(L?link(L.url,tr('2021 letter on Canada.ca','Lettre de 2021 sur Canada.ca')):esc(tr('No 2021 letter in the Privy Council Office collection.','Aucune lettre de 2021 dans la collection du Bureau du Conseil privé.')))+'</li><li>'+(S?link(S.url,tr('2024 self-assessment on Canada.ca','Autoévaluation de 2024 sur Canada.ca')):esc(tr('No 2024 self-assessment in the Privy Council Office collection.','Aucune autoévaluation de 2024 dans la collection du Bureau du Conseil privé.')))+'</li></ul>'+(S?said('recruitment',tr('Recruitment goals set in 2024 for','Objectifs de recrutement fixés en 2024 pour')+C,tr('Work on recruitment goals under way for','Travaux en cours sur des objectifs de recrutement pour')+C,tr('No recruitment goals stated in the 2024 self-assessment.','Aucun objectif de recrutement indiqué dans l’autoévaluation de 2024.'))+said('promotion',tr('Promotion goals set in 2024 for','Objectifs de promotion fixés en 2024 pour')+C,tr('Work on promotion goals under way for','Travaux en cours sur des objectifs de promotion pour')+C,tr('No promotion goals stated in the 2024 self-assessment.','Aucun objectif de promotion indiqué dans l’autoévaluation de 2024.')):'')+'<p class="gcw-small">'+esc(tr('A goal stated in a document is not evidence that it was met. Compare it with the representation and survey results for the same organization.','Un objectif inscrit dans un document ne prouve pas qu’il a été atteint. Comparez-le aux résultats de représentation et de sondage de la même organisation.'))+'</p>'+'<div class="gcw-actions">'+link(localized('call-to-action.html?org='+encodeURIComponent(o.id)+'#record'),tr('Compare commitments with results','Comparer les engagements et les résultats'),'gcw-btn gcw-btn-small')+((L||S)?button('cta-prefill',tr('Record a commitment from this document','Consigner un engagement de ce document'),'gcw-btn-small','data-url="'+esc((L||S).url)+'"'):'')+'</div>';}catch(e){const out=$('gcw-commit-cta');if(out)out.innerHTML='<p>'+esc(tr('The Call to Action record could not be loaded.','Le dossier de l’appel à l’action n’a pas pu être chargé.'))+'</p>';}}
