function showVolunteer(){open(tr('Contribute to equity work','Contribuer aux travaux sur l’équité'),'volunteer');const skills=[['data',tr('Data and quality checks','Données et vérifications')],['access',tr('Accessibility testing','Essais d’accessibilité')],['language',tr('Writing and translation','Rédaction et traduction')],['research',tr('Research and briefings','Recherche et notes')],['events',tr('Events and meetings','Événements et réunions')],['outreach',tr('Communications and network support','Communications et soutien aux réseaux')],['design',tr('Website and design testing','Essais du site et de la conception')]];$('gcw-content').innerHTML='<p>'+esc(tr('Choose your interests and available time to find a practical way to help. Suggested tasks illustrate possible contributions; availability is confirmed by the network.','Choisissez vos intérêts et le temps disponible pour trouver une façon concrète d’aider. Les tâches proposées illustrent les contributions possibles; le réseau en confirme la disponibilité.'))+'</p><form id="gcw-volunteer-form"><fieldset><legend>'+esc(tr('How would you like to contribute?','Comment souhaitez-vous contribuer?'))+'</legend><div class="gcw-checks">'+skills.map(([key,label])=>'<label><input type="checkbox" name="gcw-skill" value="'+key+'">'+esc(label)+'</label>').join('')+'</div></fieldset>'+field('gcw-volunteer-time',tr('Time available for a task','Temps disponible par tâche'),select('gcw-volunteer-time',[[15,tr('15 minutes','15 minutes')],[30,tr('30 minutes','30 minutes')],[60,tr('About an hour','Environ une heure')],[240,tr('Ongoing support','Soutien régulier')]],30))+'<div id="gcw-volunteer-matches" aria-live="polite"></div><div class="gcw-filters">'+field('gcw-volunteer-name',tr('Name','Nom'),'<input id="gcw-volunteer-name" required autocomplete="name" maxlength="150">')+field('gcw-volunteer-email',tr('Email','Courriel'),'<input id="gcw-volunteer-email" type="email" required autocomplete="email" maxlength="250">')+'</div>'+field('gcw-volunteer-org',tr('Organization, if you wish','Organisme, si vous le souhaitez'),'<input id="gcw-volunteer-org" maxlength="200">')+field('gcw-volunteer-notes',tr('Other skills, interests or access needs','Autres compétences, intérêts ou besoins d’accès'),'<textarea id="gcw-volunteer-notes" maxlength="2000"></textarea>')+'<div class="gcw-actions"><button type="submit" class="gcw-btn gcw-btn-primary">'+esc(tr('Preview contribution email','Aperçu du courriel de contribution'))+'</button></div></form><div id="gcw-volunteer-preview" hidden></div><p class="gcw-small">'+esc(tr('Contact details are not saved by this form. Your email app opens so you can review and send your message to aranpublicservants@gmail.com.','Ce formulaire n’enregistre pas vos coordonnées. Votre application de courriel s’ouvre pour que vous puissiez vérifier et envoyer votre message à aranpublicservants@gmail.com.'))+'</p>';renderVolunteerMatches();}
function matchedTasks(){const picked=[...document.querySelectorAll('[name="gcw-skill"]:checked')].map(c=>c.value),minutes=Number($('gcw-volunteer-time')?.value||30);return TASKS.filter(t=>picked.includes(t.key)&&t.minutes<=minutes);}
function renderVolunteerMatches(){const out=$('gcw-volunteer-matches');if(!out)return;const tasks=matchedTasks();out.innerHTML=tasks.length?'<h3 style="margin-top:20px">'+esc(tr('Suggested contributions','Contributions possibles'))+'</h3><ul>'+tasks.map(t=>'<li>'+esc(fr()?t.fr:t.en)+' <span class="gcw-small">('+t.minutes+' min)</span></li>').join('')+'</ul>':'<p class="gcw-empty">'+esc(tr('Select an interest to see matching tasks.','Sélectionnez un intérêt pour voir les tâches correspondantes.'))+'</p>';}
function volunteerPreview(){const picked=[...document.querySelectorAll('[name="gcw-skill"]:checked')];if(!picked.length){toast(tr('Choose at least one area of interest.','Choisissez au moins un domaine d’intérêt.'));return;}const tasks=matchedTasks(),body=[tr('I would like to contribute to equity work through ARAN.','Je souhaite contribuer aux travaux sur l’équité par l’intermédiaire du RAAR.'),tr('Name: ','Nom : ')+$('gcw-volunteer-name').value,tr('Email: ','Courriel : ')+$('gcw-volunteer-email').value,tr('Organization: ','Organisme : ')+$('gcw-volunteer-org').value,tr('Interests: ','Intérêts : ')+picked.map(c=>clean(c.parentElement.textContent)).join(', '),tr('Time available: ','Temps disponible : ')+$('gcw-volunteer-time').selectedOptions[0].text,tr('Possible tasks:','Tâches possibles :'),...tasks.map(t=>'• '+(fr()?t.fr:t.en)),tr('Other information: ','Autres renseignements : ')+$('gcw-volunteer-notes').value].join('\n');const out=$('gcw-volunteer-preview');out.hidden=false;out.innerHTML=field('gcw-email-body',tr('Email preview','Aperçu du courriel'),'<textarea id="gcw-email-body" rows="11" readonly>'+esc(body)+'</textarea>')+'<div class="gcw-actions"><a class="gcw-btn gcw-btn-primary" href="mailto:aranpublicservants@gmail.com?subject='+encodeURIComponent(tr('Contribution to ARAN equity work','Contribution aux travaux du RAAR sur l’équité'))+'&body='+encodeURIComponent(body)+'">'+esc(tr('Open email to review and send','Ouvrir le courriel pour vérifier et envoyer'))+'</a>'+button('copy-volunteer',tr('Copy message','Copier le message'))+'</div>';out.scrollIntoView({block:'nearest'});}

/* Saved views include supported filters in shareable links. */
const FILTER_IDS=['opOrg','deptSel','gcGroup','eqCompareGroup','eqCompareQuestion','eqCompareSurveyGroup','cmpA','cmpB','allDeptFilter','allDeptTier','yoyOrg','yoyQ','demoQuestion','demoGroup','indDept','briefOrg','eqBranchQuestion','eqBranchGroup','eqBranchAnswer','search','type','size','group','mention','view','sort'];
function viewURL(){const u=new URL(location.href),state={};for(const id of FILTER_IDS){const el=$(id);if(el&&el.getClientRects().length&&((el.tagName==='SELECT'&&el.options.length)||el.tagName==='INPUT')&&el.value!==undefined)state[id]=String(el.value).slice(0,250);}u.searchParams.delete('wsv');if(Object.keys(state).length)u.searchParams.set('wsv',btoa(unescape(encodeURIComponent(JSON.stringify(state)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''));return u.href;}
function currentViewName(){if($('opOrg')&&location.hash.match(/departments|orgprofile/))return $('opOrg').selectedOptions[0]?.textContent||document.title;const active=[...document.querySelectorAll('section.view.active')].find(s=>s.getBoundingClientRect().bottom>100);return clean(active?.querySelector('h2')?.textContent||document.querySelector('h1')?.textContent||document.title).slice(0,120);}
function showViews(){open(tr('Saved views','Vues enregistrées'),'views');$('gcw-content').innerHTML='<p>'+esc(tr('Save a department, group or combination of filters. The link can be shared without an account.','Enregistrez un organisme, un groupe ou une combinaison de filtres. Le lien peut être partagé sans compte.'))+'</p><form id="gcw-save-view-form"><div class="gcw-filters">'+field('gcw-view-name',tr('Name for this view','Nom de cette vue'),'<input id="gcw-view-name" required maxlength="150" value="'+esc(currentViewName())+'">')+'</div><div class="gcw-actions"><button class="gcw-btn gcw-btn-primary" type="submit">'+esc(tr('Save current view','Enregistrer la vue actuelle'))+'</button>'+button('copy-view',tr('Copy shareable link','Copier le lien partageable'))+'</div></form><div id="gcw-views-list"></div><div class="gcw-actions">'+button('export-views',tr('Export saved views','Exporter les vues'))+button('import-views',tr('Import saved views','Importer les vues'))+'<input id="gcw-import-views-file" type="file" accept=".json,application/json" hidden></div><p class="gcw-small">'+esc(tr('Saved links restore the supported filters from the current page. Briefing notes, contact details and working records are not included in shared links.','Les liens enregistrés rétablissent les filtres pris en charge dans la page actuelle. Ils ne contiennent pas vos notes, coordonnées ni dossiers de travail.'))+'</p>';renderViews();}
function renderViews(){const host=$('gcw-views-list');if(host)host.innerHTML=views.length?views.map((v,i)=>'<article class="gcw-result"><h3>'+link(v.url,v.name)+'</h3><div class="gcw-actions">'+button('remove-view',tr('Remove','Retirer'),'gcw-btn-small','data-index="'+i+'"')+'</div></article>').join(''):'<p class="gcw-empty">'+esc(tr('No saved views yet.','Aucune vue enregistrée pour le moment.'))+'</p>';renderHomeViews();}
function renderHomeViews(){const host=$('gcw-home-views');if(host)host.innerHTML=views.slice(-4).reverse().map(v=>'<div class="gcw-saved-card">'+link(v.url,v.name)+'<span aria-hidden="true">→</span></div>').join('');}
function restoreView(){const requestedOrg=new URL(location.href).searchParams.get('org');if(requestedOrg&&$('opOrg')){const el=$('opOrg');if([...el.options].some(o=>o.value===requestedOrg)){el.value=requestedOrg;el.dispatchEvent(new Event('change',{bubbles:true}));}}const encoded=new URL(location.href).searchParams.get('wsv');if(!encoded||encoded.length>12000)return;let state;try{state=JSON.parse(decodeURIComponent(escape(atob(encoded.replace(/-/g,'+').replace(/_/g,'/')))));}catch{return;}if(!state||typeof state!=='object')return;let attempts=0;const done=new Set();function apply(){for(const id of FILTER_IDS){if(done.has(id)||!(id in state))continue;const el=$(id),v=String(state[id]).slice(0,250);if(!el)continue;if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===v))continue;el.value=v;el.dispatchEvent(new Event(el.tagName==='INPUT'?'input':'change',{bubbles:true}));done.add(id);}if(++attempts<15&&FILTER_IDS.some(k=>k in state&&!done.has(k)))setTimeout(apply,400);}setTimeout(apply,300);}
