/* Capture rendered tables, chart snapshots and the source details beside them. */
function sanitizeSVG(svg){if(typeof svg!=='string'||svg.length>150000)return '';const doc=new DOMParser().parseFromString(svg,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')return '';const tags=new Set(['svg','g','path','rect','circle','ellipse','line','polyline','polygon','text','tspan','title','desc','defs','clipPath','linearGradient','stop']);const attrs=new Set(['xmlns','viewBox','width','height','x','y','x1','x2','y1','y2','cx','cy','r','rx','ry','d','points','fill','stroke','stroke-width','stroke-dasharray','opacity','fill-opacity','stroke-opacity','transform','font-size','font-family','font-weight','text-anchor','dominant-baseline','role','aria-label','id','offset','stop-color','stop-opacity','clip-path']);for(const el of [...doc.querySelectorAll('*')]){if(!tags.has(el.localName)){el.remove();continue;}for(const a of [...el.attributes])if(!attrs.has(a.name)||/javascript:|data:|expression\(|https?:|url\((?!#[\w-]+\))/.test(a.value))el.removeAttribute(a.name);}doc.documentElement.setAttribute('xmlns','http://www.w3.org/2000/svg');return new XMLSerializer().serializeToString(doc.documentElement);}
function captureFact(target){const section=target.closest('section.view,section,article,.card')||document.querySelector('main')||document.body;const caption=clean(target.caption?.textContent||target.querySelector?.('title')?.textContent||section.querySelector('h2,h3,h4')?.textContent||document.title);const sources=[...section.querySelectorAll('a[href]')].map(a=>({url:url(a.getAttribute('href')),title:clean(a.textContent)})).filter(s=>s.url&&(/canada\.ca|statcan\.gc\.ca|psc-cfp\.gc\.ca|employment-equity\.github\.io|data\/october/.test(s.url))).slice(0,12);let f={title:caption,text:tr('Snapshot from the displayed data view.','Instantané de la vue de données affichée.'),url:viewURL(),source:sources[0]?.url||location.href,sourceTitle:sources[0]?.title||tr('Supporting data view','Vue justificative'),sources,period:tr('As labelled in the table or chart; see the supporting view','Selon le tableau ou le graphique; voir la vue justificative'),population:tr('As specified by the supporting table. Different sections can cover different populations.','Selon le tableau justificatif. Les sections peuvent couvrir des populations différentes.'),calculation:tr('Values as displayed. Source-specific calculations and suppression rules remain in the supporting view.','Valeurs affichées. Les calculs et les règles de suppression propres à la source restent dans la vue justificative.'),limitation:tr('This is a saved snapshot. It does not update automatically when source data change. A difference is not a finding of discrimination.','Cet instantané ne se met pas à jour lorsque les données sources changent. Un écart n’est pas une constatation de discrimination.'),kind:target.tagName.toLowerCase()==='table'?'table':'chart'};
 if(f.kind==='table'){const rows=[...target.rows];f.table=rows.slice(0,251).map(r=>[...r.cells].map(c=>clean(c.textContent)));if(rows.length>251)f.text+=tr(' The snapshot includes the first 250 data rows. Use the data view’s CSV download for all rows.',' L’instantané contient les 250 premières lignes de données. Utilisez le téléchargement CSV de la vue pour obtenir toutes les lignes.');}
 else f.chart=sanitizeSVG(new XMLSerializer().serializeToString(target));return f;}
function enhanceTables(root=document){const main=root.querySelector?.('main')||root;main.querySelectorAll('table').forEach(t=>{if(t.closest('.gcw-dialog')||t.dataset.gcwReady)return;t.dataset.gcwReady='yes';const bar=document.createElement('div');bar.className='gcw-capture';bar.innerHTML=button('capture-table',tr('Save table','Retenir le tableau'),'gcw-btn-small')+button('trace-table',tr('Table sources','Sources du tableau'),'gcw-btn-small');bar._gcwTarget=t;const wrapper=t.closest('.tblwrap,.eq-table-scroll,.eq-native-table-wrap,.table-scroll,.scroll')||t;wrapper.before(bar);t.querySelectorAll('td').forEach(td=>{if(td.children.length||!/^[-+−]?\d[\d,.\s]*%?$/.test(clean(td.textContent)))return;const b=document.createElement('button');b.type='button';b.className='gcw-number';b.dataset.gcw='trace-cell';b.textContent=td.textContent;b.setAttribute('aria-label',tr('Source for ','Source de ')+clean(td.parentElement.cells[0]?.textContent)+' · '+clean(t.tHead?.rows[t.tHead.rows.length-1]?.cells[td.cellIndex]?.textContent)+' · '+clean(td.textContent));td.replaceChildren(b);});});main.querySelectorAll('svg').forEach(svg=>{if(svg.dataset.gcwReady||svg.closest('button,.gcw-dialog')||(!svg.getAttribute('viewBox')&&!svg.querySelector('text')))return;svg.dataset.gcwReady='yes';const bar=document.createElement('div');bar.className='gcw-capture';bar.innerHTML=button('capture-chart',tr('Save chart','Retenir le graphique'),'gcw-btn-small');bar._gcwTarget=svg;svg.after(bar);});}


