function renderStart(m){const org=$('gcw-start-org')?.value||'Public Service',g=m.groups.find(g=>g.key===$('gcw-start-group')?.value)||m.groups[3];$('gcw-start-link').href=localized('explorer.html?'+(org==='Public Service'?'group='+g.picker:'org='+encodeURIComponent(org))+(org==='Public Service'?'#data':'#orgprofile'));const f=repFact(m,g,org);$('gcw-start-result').innerHTML=f?'<p class="gcw-small">'+esc(f.period)+' · '+esc(f.text)+'</p>'+factActions(f):'<p class="gcw-small">'+esc(tr('Open the data view to check the published coverage for this group.','Ouvrez la vue pour vérifier les données publiées pour ce groupe.'))+'</p>';}
function addContext(){if($('gcw-home'))return;const el=document.createElement('div');el.id='gcw-context';el.className='gcw-context';el.innerHTML=(location.pathname.endsWith('explorer.html')?'<div><span class="gcw-small">GC Equity · Équité-GC</span><h1 class="gcw-view-title">'+esc(location.hash.match(/departments|orgprofile/)?tr('Department and agency data','Données des ministères et organismes'):location.hash.match(/bhome|brief|action/)?tr('Briefings and tools','Notes et outils'):tr('Public service data','Données de la fonction publique'))+'</h1></div>':'<span>'+esc(tr('GC Equity research workspace','Espace de recherche Équité-GC'))+'</span>')+'<div class="gcw-actions">'+button('views',tr('Save or share this view','Enregistrer ou partager la vue'),'gcw-btn-small')+button('guide',tr('Ask the data guide','Consulter le guide'),'gcw-btn-small')+'</div>';$('gcw-header').after(el);}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast(tr('Copied.','Copié.'));}catch{const ta=document.createElement('textarea');ta.value=s;ta.style.position='fixed';ta.style.left='-9999px';(dialog.open?dialog:document.body).append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();toast(ok?tr('Copied.','Copié.'):tr('Copy was unavailable. Select and copy the text manually.','La copie est indisponible. Sélectionnez et copiez le texte manuellement.'));}}
function setLanguage(next){try{localStorage.setItem('gcEquityLang',next);}catch{}document.documentElement.lang=next;const u=new URL(location.href);if(next==='fr')u.searchParams.set('lang','fr');else u.searchParams.delete('lang');history.replaceState(history.state,'',u.href);if(typeof window._applyLang==='function')window._applyLang(next);else if(typeof window.gcSetLang==='function')window.gcSetLang(next);else{const old=document.querySelector('[data-lang-btn="'+next+'"]');if(old)old.click();else if($('language')&&((document.documentElement.lang.startsWith('fr')?'fr':'en')!==$('language').dataset.currentLang)){$('language').click();}}renderHeader();renderFooter();renderHome();const context=$('gcw-context');if(context){context.remove();addContext();}$('gcw-lang')?.focus();}
function setTheme(theme){if(!['dark','contrast'].includes(theme))theme='light';if(theme==='light')delete document.documentElement.dataset.theme;else document.documentElement.dataset.theme=theme;try{localStorage.setItem('gcEquityTheme',theme);}catch{}document.querySelectorAll('[data-theme-set]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeSet===theme)));}
async function openTool(name){if(name==='search')return showSearch();if(name==='guide')return showGuide();if(name==='basket')return showBasket();if(name==='changes')return showChanges();if(name==='history')return showHistory();if(name==='commitments')return showCommitments();if(name==='volunteer')return showVolunteer();if(name==='views')return showViews();if(name==='related')return showRelated();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-gcw]');if(!b)return;const action=b.dataset.gcw;if(['search','guide','basket','changes','history','commitments','volunteer','views','related'].includes(action)){e.preventDefault();return openTool(action);}if(action==='close')return dialog.close();if(action==='close-trace')return $('gcw-trace')?.close();if(action==='language')return setLanguage(fr()?'en':'fr');if(action==='retry')return openTool(activePanel);if(action==='save-fact')return saveFact(getFact(b.dataset.fact));if(action==='trace-fact')return showTrace(getFact(b.dataset.fact));if(action==='basket-trace')return showTrace(basket[Number(b.dataset.index)]);
 if(action==='basket-remove'||action==='basket-up'){const i=Number(b.dataset.index);const next=basket.slice();if(action==='basket-remove')next.splice(i,1);else if(i>0)[next[i],next[i-1]]=[next[i-1],next[i]];if(write('evidence',next)){evidenceText();basket=next;updateCounts();showBasket();}return;}
 if(action==='export-html')return download('GC-Equity-Briefing.html',briefingHTML(),'text/html;charset=utf-8');if(action==='export-text')return download('GC-Equity-Briefing.txt',evidenceText());if(action==='export-json'){evidenceText();return download('GC-Equity-Evidence.json',JSON.stringify({schema:1,evidence:basket,brief:read('brief',{})},null,2),'application/json');}if(action==='import-json')return $('gcw-import-file').click();if(action==='export-views')return download('GC-Equity-Views.json',JSON.stringify({schema:1,views},null,2),'application/json');if(action==='import-views')return $('gcw-import-views-file').click();
 if(action==='guide-example'){$('gcw-guide-query').value=b.dataset.question;return answerQuestion(b.dataset.question);}if(action==='history-event')return renderHistory(await model(),Number(b.dataset.index));if(action==='copy-view')return copyText(viewURL());if(action==='remove-view'){const next=views.filter((_,i)=>i!==Number(b.dataset.index));if(write('views',next)){views=next;renderViews();}return;}if(action==='remember-start'){if(write('start',{org:$('gcw-start-org').value,group:$('gcw-start-group').value}))toast(tr('Starting choices saved in this browser.','Choix de départ enregistrés dans ce navigateur.'));return;}
 if(action==='copy-volunteer')return copyText($('gcw-email-body').value);if(action==='cta-prefill'){const d=$('gcw-commit-form-details');if(d)d.open=true;const src=$('gcw-commit-source');if(src)src.value=b.dataset.url||'';$('gcw-commit-title')?.focus();return;}if(action==='remove-commitment'){const next=commitments.filter((_,i)=>i!==Number(b.dataset.index));if(write('commitments',next)){commitments=next;renderCommitRecords();}return;}if(action==='export-commitments')return download('GC-Equity-Working-Records.csv','\uFEFF'+[['Organization','Commitment','Source URL','Responsible function','Target date','Evidence status','Outcome evidence and limits'],...commitments.map(r=>[r.org,r.title,r.source,r.owner,r.date,r.status,r.note])].map(r=>r.map(safeCSV).join(',')).join('\r\n'),'text/csv;charset=utf-8');
 if(['capture-table','capture-chart','trace-table'].includes(action)){const target=b.closest('.gcw-capture')._gcwTarget;if(!target)return;const f=captureFact(target);return action==='trace-table'?showTrace(f):saveFact(f);}if(action==='trace-cell'){const cell=b.closest('td'),t=cell.closest('table'),f=captureFact(t),head=clean(t.tHead?.rows[t.tHead.rows.length-1]?.cells[cell.cellIndex]?.textContent),row=clean(cell.parentElement.cells[0]?.textContent);f.title+= ' · '+row+(head?' · '+head:'');f.text=clean(b.textContent);delete f.table;return showTrace(f);}
});
document.addEventListener('submit',e=>{const id=e.target.id;if(!id.startsWith('gcw-'))return;e.preventDefault();if(id==='gcw-home-search')return showSearch($('gcw-home-query').value.trim());if(id==='gcw-search-form')return runSearch();if(id==='gcw-guide-form')return answerQuestion($('gcw-guide-query').value.trim());if(id==='gcw-volunteer-form')return volunteerPreview();if(id==='gcw-save-view-form'){const next=[...views,{name:$('gcw-view-name').value.trim(),url:viewURL(),saved:new Date().toISOString()}].slice(-30);if(write('views',next)){views=next;renderViews();toast(tr('View saved.','Vue enregistrée.'));}return;}if(id==='gcw-commit-form'){const source=url($('gcw-commit-source').value);if(!source){$('gcw-commit-error').textContent=tr('Use a valid http or https source address.','Utilisez une adresse de source http ou https valide.');return;}const record={id:crypto.randomUUID(),org:$('gcw-commit-org').value,title:$('gcw-commit-title').value.trim(),source,owner:$('gcw-commit-owner').value.trim(),date:$('gcw-commit-date').value,status:$('gcw-commit-status').value,note:$('gcw-commit-note').value.trim()};const next=[...commitments,record].slice(-100);if(write('commitments',next)){commitments=next;e.target.reset();renderCommitRecords();toast(tr('Working record saved in this browser.','Dossier de travail enregistré dans ce navigateur.'));}}});
